using BARANG.Core.Api.Errors;
using BARANG.Core.Application.Abstractions.Correlation;
using BARANG.Core.Application.Orders;
using BARANG.Core.Domain.Common;
using BARANG.Core.Domain.Orders;
using BARANG.Core.Domain.Security;
using BARANG.Core.Application.Files;
using BARANG.Core.Domain.Files;
using Microsoft.AspNetCore.Mvc;

namespace BARANG.Core.Api.Orders;

public static class OrderEndpoints
{
    public static IEndpointRouteBuilder MapOrderEndpoints(this IEndpointRouteBuilder e)
    {
        RouteGroupBuilder root = e.MapGroup("/api/v1/orders"); RouteGroupBuilder read = root.MapGroup("").RequireAuthorization(SecurityPermissions.OrderRead); read.MapGet("/", async ([AsParameters] OrderSearchRequest r, IOrderAdministration s, CancellationToken ct) => Map(await s.SearchAsync(r.Query(), ct))); read.MapGet("/{id:guid}", async (Guid id, IOrderAdministration s, CancellationToken ct) => Map(await s.GetAsync(id, ct))); read.MapGet("/{id:guid}/timeline", async (Guid id, IOrderAdministration s, CancellationToken ct) => Map(await s.TimelineAsync(id, ct))); read.MapGet("/{id:guid}/validation", async (Guid id, IOrderAdministration s, CancellationToken ct) => Map(await s.ValidateAsync(id, ct)));
        root.MapPost("/", async (CreateDraftCommand r, IOrderAdministration s, CancellationToken ct) => Map(await s.CreateDraftAsync(r, ct), true)).RequireAuthorization(SecurityPermissions.OrderCreate);
        RouteGroupBuilder manage = root.MapGroup("").RequireAuthorization(SecurityPermissions.OrderManage); manage.MapPut("/{id:guid}", async (Guid id, EditDraftCommand r, IOrderAdministration s, CancellationToken ct) => Map(await s.EditDraftAsync(id, r, ct))); manage.MapPut("/{id:guid}/shipping-address", async (Guid id, AddressCommand r, IOrderAdministration s, CancellationToken ct) => Map(await s.SetShippingAsync(id, r, ct))); manage.MapPost("/{id:guid}/items", async (Guid id, ItemCommand r, IOrderAdministration s, CancellationToken ct) => Map(await s.AddItemAsync(id, r, ct), true)); manage.MapPut("/{id:guid}/items/{itemId:guid}", async (Guid id, Guid itemId, ItemCommand r, IOrderAdministration s, CancellationToken ct) => Map(await s.UpdateItemAsync(id, itemId, r, ct))); manage.MapPost("/{id:guid}/items/{itemId:guid}/remove", async (Guid id, Guid itemId, VersionRequest r, IOrderAdministration s, CancellationToken ct) => Map(await s.RemoveItemAsync(id, itemId, r.Version, ct))); manage.MapPost("/{id:guid}/items/{itemId:guid}/print-operations", async (Guid id, Guid itemId, PrintOperationCommand r, IOrderAdministration s, CancellationToken ct) => Map(await s.AddPrintAsync(id, itemId, r, ct), true)); manage.MapPut("/{id:guid}/items/{itemId:guid}/print-operations/{operationId:guid}", async (Guid id, Guid itemId, Guid operationId, PrintOperationCommand r, IOrderAdministration s, CancellationToken ct) => Map(await s.UpdatePrintAsync(id, itemId, operationId, r, ct))); manage.MapPost("/{id:guid}/items/{itemId:guid}/print-operations/{operationId:guid}/remove", async (Guid id, Guid itemId, Guid operationId, VersionRequest r, IOrderAdministration s, CancellationToken ct) => Map(await s.RemovePrintAsync(id, itemId, operationId, r.Version, ct))); manage.MapPost("/{id:guid}/change-requests", async (Guid id, ChangeRequestCommand r, IOrderAdministration s, CancellationToken ct) => Map(await s.CreateChangeRequestAsync(id, r, ct), true)).RequireAuthorization(SecurityPermissions.OrderChangeRequestManage);
        root.MapPost("/{id:guid}/files/{fileId:guid}/links", async (Guid id, Guid fileId, OrderFileLinkRequest r, IArtworkFileAdministration s, CancellationToken ct) => Map(await s.LinkFileAsync(fileId, r.FileVersionId, FileLinkEntityType.Order, id, r.Purpose, ct), true)).RequireAuthorization(SecurityPermissions.OrderManage, SecurityPermissions.FileManage);
        root.MapPost("/{id:guid}/items/{itemId:guid}/files/{fileId:guid}/links", async (Guid id, Guid itemId, Guid fileId, OrderFileLinkRequest r, IArtworkFileAdministration s, CancellationToken ct) => Map(await s.LinkFileAsync(fileId, r.FileVersionId, FileLinkEntityType.OrderItem, itemId, r.Purpose, ct), true)).RequireAuthorization(SecurityPermissions.OrderManage, SecurityPermissions.FileManage);
        root.MapPost("/{id:guid}/items/{itemId:guid}/print-operations/{operationId:guid}/files/{fileId:guid}/links", async (Guid id, Guid itemId, Guid operationId, Guid fileId, OrderFileLinkRequest r, IArtworkFileAdministration s, CancellationToken ct) => Map(await s.LinkFileAsync(fileId, r.FileVersionId, FileLinkEntityType.OrderPrintOperation, operationId, r.Purpose, ct), true)).RequireAuthorization(SecurityPermissions.OrderManage, SecurityPermissions.FileManage);
        root.MapPost("/{id:guid}/submit", async (Guid id, VersionRequest r, IOrderAdministration s, CancellationToken ct) => Map(await s.SubmitAsync(id, r.Version, ct))).RequireAuthorization(SecurityPermissions.OrderSubmit); root.MapPost("/{id:guid}/cancel", async (Guid id, CancelOrderCommand r, IOrderAdministration s, CancellationToken ct) => Map(await s.CancelAsync(id, r, ct))).RequireAuthorization(SecurityPermissions.OrderCancel); return e;
    }
    private static OrderResult Map(Result r) => new(r); private static OrderResult<T> Map<T>(Result<T> r, bool created = false) => new(r, created); private sealed class OrderResult(Result result) : IResult { public Task ExecuteAsync(HttpContext c) { if (result.IsSuccess) { c.Response.StatusCode = 204; return Task.CompletedTask; } IResult p = Results.Problem(ApiProblemDetailsMapper.Create(result.Error, c.TraceIdentifier, c.Request.Path)); return p.ExecuteAsync(c); } }
    private sealed class OrderResult<T>(Result<T> result, bool created) : IResult { public Task ExecuteAsync(HttpContext c) { if (result.IsSuccess) { c.Response.StatusCode = created ? 201 : 200; return c.Response.WriteAsJsonAsync(result.Value, c.RequestAborted); } IResult p = Results.Problem(ApiProblemDetailsMapper.Create(result.Error, c.TraceIdentifier, c.Request.Path)); return p.ExecuteAsync(c); } }
}
public sealed record VersionRequest(long Version);
public sealed record OrderFileLinkRequest(Guid FileVersionId, FileLinkPurpose Purpose);
public sealed record OrderSearchRequest(string? OrderNumber, Guid? CustomerId, string? CustomerSearch, OrderStatus? Status, Guid? BranchId, OrderSource? Source, DateOnly? OrderDateFrom, DateOnly? OrderDateTo, DateTimeOffset? SubmittedFrom, DateTimeOffset? SubmittedTo, string? ExternalReference, int? Page, int? PageSize) { public OrderSearchQuery Query() => new(OrderNumber, CustomerId, CustomerSearch, Status, BranchId, Source, OrderDateFrom, OrderDateTo, SubmittedFrom, SubmittedTo, ExternalReference, Page ?? 1, PageSize ?? 20); }
